const clientData = $('Store Client Config').first().json;
const client = clientData.client;

// Get data from both sources
const newsApiResult = $('Fetch News API').first().json;
const rssItems = $('Fetch RSS Feeds').all().map(item => item.json);

const newsApiData = newsApiResult?.articles || [];
const excludeKeywords = client.sources.excludeKeywords || [];

// Normalize news items
const allNews = [];

// Process NewsAPI articles
newsApiData.forEach(article => {
  // Check for excluded keywords
  const text = (article.title + ' ' + (article.description || '')).toLowerCase();
  if (excludeKeywords.some(kw => text.includes(kw.toLowerCase()))) return;

  allNews.push({
    title: article.title,
    description: article.description || '',
    url: article.url,
    source: article.source?.name || 'NewsAPI',
    publishedAt: article.publishedAt,
    imageUrl: article.urlToImage || '',
    content: article.content || ''
  });
});

// Process RSS items
rssItems.forEach(item => {
  if (!item.title) return;

  const text = (item.title + ' ' + (item.contentSnippet || '')).toLowerCase();
  if (excludeKeywords.some(kw => text.includes(kw.toLowerCase()))) return;

  allNews.push({
    title: item.title,
    description: item.contentSnippet || item.content || '',
    url: item.link,
    source: item.creator || 'RSS Feed',
    publishedAt: item.pubDate || item.isoDate,
    imageUrl: item.enclosure?.url || '',
    content: item.content || ''
  });
});

// Remove duplicates
const seen = new Set();
const uniqueNews = allNews.filter(article => {
  const normalizedTitle = article.title.toLowerCase().substring(0, 50);
  if (seen.has(normalizedTitle)) return false;
  seen.add(normalizedTitle);
  return true;
});

// Sort by date and limit
const maxArticles = client.preferences.maxArticles || 15;
const sortedNews = uniqueNews
  .sort((a, b) => new Date(b.publishedAt) - new Date(a.publishedAt))
  .slice(0, maxArticles);

return [{ 
  json: { 
    client,
    articles: sortedNews, 
    count: sortedNews.length 
  } 
}];

