const inputData = $('Has Articles?').first().json;
const client = inputData.client;
const articles = inputData.articles;
const aiResponse = $input.first().json.message?.content || $input.first().json.text || '{"categorized":[]}';

// Parse AI response
let categorized = [];
try {
  const parsed = JSON.parse(aiResponse.replace(/```json\n?|```/g, '').trim());
  categorized = parsed.categorized || [];
} catch (e) {
  // Fallback: keyword-based categorization
  categorized = articles.map((article, i) => {
    const text = (article.title + ' ' + article.description).toLowerCase();
    let category = 'Other';

    for (const [cat, data] of Object.entries(client.categories)) {
      if (data.keywords && data.keywords.some(kw => text.includes(kw))) {
        category = cat;
        break;
      }
    }

    return { id: i, category, summary: article.description.substring(0, 100), importance: 5 };
  });
}

// Enrich articles
const enrichedArticles = articles.map((article, index) => {
  const catInfo = categorized.find(c => c.id === index) || {
    category: 'Other',
    summary: article.description.substring(0, 100),
    importance: 5
  };

  const categoryData = client.categories[catInfo.category] || client.categories['Other'] || { icon: '📰', color: '#6B7280' };

  return {
    ...article,
    category: catInfo.category,
    categoryIcon: categoryData.icon,
    categoryColor: categoryData.color,
    summary: catInfo.summary,
    importance: catInfo.importance
  };
});

// Find top story
const sortedByImportance = [...enrichedArticles].sort((a, b) => b.importance - a.importance);
const topStory = sortedByImportance[0];

// Group by category
const groupedByCategory = {};
enrichedArticles.forEach(article => {
  if (!groupedByCategory[article.category]) {
    groupedByCategory[article.category] = {
      icon: article.categoryIcon,
      color: article.categoryColor,
      articles: []
    };
  }
  groupedByCategory[article.category].articles.push(article);
});

return [{ 
  json: { 
    client,
    topStory,
    categories: groupedByCategory,
    totalArticles: enrichedArticles.length
  } 
}];

