      <div class="toc-list">
`;

for (const [catName, catData] of Object.entries(categories)) {
  html += `<span class="toc-item"><span>${catData.icon}</span><span>${catName}</span><span class="toc-count">${catData.articles.length}</span></span>`;
}

html += `
      </div>
