const { client, topStory, categories } = $input.first().json;
const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' });

const esc = (text) => text.replace(/[_*\[\]()~`>#+=|{}.!-]/g, '\\$&');

let msg = `*${esc(client.branding.newsletterTitle)}*\n`;
msg += `_${esc(client.industry)} • ${esc(today)}_\n`;
msg += '━━━━━━━━━━━━━━━━━━━━\n\n';

msg += `⭐ *TOP STORY*\n`;
msg += `${topStory.categoryIcon} [${esc(topStory.title.substring(0, 60))}](${topStory.url})\n`;
msg += `_${esc(topStory.summary)}_\n\n`;
msg += '━━━━━━━━━━━━━━━━━━━━\n\n';

let count = 0;
for (const [catName, catData] of Object.entries(categories)) {
  if (count >= 6) break;
  msg += `${catData.icon} *${esc(catName)}*\n`;
  catData.articles.slice(0, 2).forEach(a => {
    if (count >= 6) return;
    msg += `  • [${esc(a.title.substring(0, 50))}...](${a.url})\n`;
    count++;
  });
  msg += '\n';
}

const total = Object.values(categories).reduce((s, c) => s + c.articles.length, 0);
if (total > 6) msg += `📧 _\\+${total - 6} more in email_\n`;

msg += '\n━━━━━━━━━━━━━━━━━━━━';
